import React from 'react';

function App() {
  return (
    <div style={{ textAlign: 'center', marginTop: '50px' }}>
      <h1>📚 Personal Media Collection Manager</h1>
      <p>Welcome to your media collection tracker!</p>
      <p>Frontend is set up successfully! 🚀</p>
    </div>
  );
}

export default App;
